	/** 
	 * jumpstart the process by instantiating2 Gateway
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		gatewayId = GatewayService.getGatewayInstance()
		.createGateway( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		GatewayService.getGatewayInstance()
				.createGateway( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.gatewaySubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Gateway : " + successValue.getGatewayId());
							  if (successValue.getGatewayId().equals(gatewayId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfGatewayList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Gateway test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on gateway consumed")
					);
			subscriber.gatewaySubscribe( gatewayId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Gateway : " + successValue.getGatewayId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfGatewayList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on gateway for gatewayId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Gateway. 
	 */
	protected Gateway read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Gateway" );

		Gateway entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Gateway with primary key" );
		msg.append( gatewayId );
		
		GatewayFetchOneSummary fetchOneSummary = new GatewayFetchOneSummary( gatewayId );

		try {
			entity = GatewayService.getGatewayInstance().getGateway( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Gateway " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Gateway.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Gateway." );

		StringBuilder msg = new StringBuilder( "Failed to update a Gateway : " );        
		Gateway entity = read();
		UpdateGatewayCommand command = generateUpdateCommand();
		command.setGatewayId(entity.getGatewayId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Gateway." );

			// for use later on...
			gatewayId = entity.getGatewayId();

			GatewayService proxy = GatewayService.getGatewayInstance();  

			proxy.updateGateway( command ).get();

			LOGGER.info( "-- Successfully saved Gateway - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + gatewayId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Gateway.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Gateway." );

		Gateway entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Gateway with id " + gatewayId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Gateway with id " + gatewayId );

			throw e;
		}

		try{
			GatewayService.getGatewayInstance().delete( new DeleteGatewayCommand( entity.getGatewayId() ) ).get();
			LOGGER.info( "-- Successfully deleted Gateway with id " + gatewayId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Gateway with id " + gatewayId );

			throw e;
		}
	}

	/**
	 * get all Gateways.
	 */
	protected List<Gateway> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Gateways:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Gateway : " );        
		List<Gateway> collection  = new ArrayList<>();

		try {
			// call the static get method on the GatewayService
			collection = GatewayService.getGatewayInstance().getAllGateway();
			assertNotNull( collection, "An Empty collection of Gateway was incorrectly returned.");
			
			// Now print out the values
			Gateway entity = null;            
			Iterator<Gateway> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getGatewayId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

